// @generated by:gauntlet run:godseye-local-backend
import { randomUUID } from "node:crypto";
import { readdir } from "node:fs/promises";
import { afterEach, describe, expect, it } from "vitest";
import { type BackendFixture, backendFixture } from "./backend-fixture.js";

describe("application request epoch captured across body IO", () => {
  let fixture: BackendFixture | undefined;
  afterEach(async () => fixture?.close());

  it("T-AC-55 rejects a request whose body arrives after a lifecycle epoch change while admitting a fresh request", async () => {
    fixture = await backendFixture();
    const cookie = (await fixture.register()).cookie;
    let ready: (() => void) | undefined;
    let supply: ((bytes: Uint8Array) => void) | undefined;
    const reading = new Promise<void>((resolve) => {
      ready = resolve;
    });
    const stream = new ReadableStream<Uint8Array>(
      {
        start(controller) {
          supply = (bytes) => {
            controller.enqueue(bytes);
            controller.close();
          };
        },
        pull() {
          ready?.();
        },
      },
      { highWaterMark: 0 },
    );
    const body = { name: "epoch.txt", contentType: "text/plain", size: 1 };
    const before = await readdir(fixture.filesRoot);
    const pending = fixture.request("/files", {
      method: "POST",
      headers: { cookie, "content-type": "application/json", "idempotency-key": randomUUID() },
      body: stream,
      duplex: "half",
    } as RequestInit & { duplex: "half" });
    await reading;
    fixture.lifecycle.epoch++;
    supply?.(new TextEncoder().encode(JSON.stringify(body)));
    expect((await pending).status).toBe(423);
    expect(await readdir(fixture.filesRoot)).toEqual(before);
    const fresh = await fixture.json("/files", body, { cookie, "idempotency-key": randomUUID() });
    expect(fresh.status).toBe(201);
  });
});
